WITH valid AS (SELECT id, supplier_name, country, rating, CASE WHEN rating >= 4.3 THEN 'High' WHEN rating >= 2.1 THEN 'Medium' ELSE 'Low' END AS rating_tier FROM suppliers WHERE city IS NOT NULL AND supplier_name IS NOT NULL) SELECT CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END AS rating_tier, country, COUNT(CASE WHEN country = 'TH' THEN 1 END) AS th_count, SUM(rating) AS total_rating, PERCENT_RANK() OVER (PARTITION BY CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY COUNT(CASE WHEN country = 'TH' THEN 1 END) DESC) AS th_count_percent_rank FROM valid GROUP BY CASE WHEN rating >= 4.6 THEN 'PREMIUM' ELSE 'STANDARD' END, country ORDER BY country NULLS LAST
